  'どうしても': { ex: 'どうしても、この映画が見たいんです。', rom: 'どうしても、このえいががみたいんです。', ko: '무슨 일이 있어도 이 영화를 꼭 보고 싶어요.' },
  '全く': { ex: '彼の話は全く理解できませんでした。', rom: 'かれのはなしはまったくりかいできませんでした。', ko: '그의 이야기는 전혀 이해할 수 없었어요.' },
  '粗': { ex: '他人の粗ばかり探すのはやめましょう。', rom: 'たにんのあらばかりさがすのはやめましょう。', ko: '남의 흠만 찾는 건 그만둬요.' },
  '認める': { ex: '彼はやっと自分の間違いを認めました。', rom: 'かれはやっとじぶんのまちがいをみとめました。', ko: '그는 겨우 자기 잘못을 인정했어요.' },
  '元': { ex: '使ったはさみは元の場所に戻してください。', rom: 'つかったはさみはもとのばしょにもどしてください。', ko: '쓴 가위는 원래 자리에 돌려놓으세요.' },
  '基': { ex: 'この映画は実話を基に作られました。', rom: 'このえいがはじつわをもとにつくられました。', ko: '이 영화는 실화를 바탕으로 만들어졌어요.' },
  '素': { ex: 'お湯にスープの素を入れて混ぜます。', rom: 'おゆにスープのもとをいれてまぜます。', ko: '뜨거운 물에 수프 분말을 넣고 저어요.' },
  '仲間': { ex: 'サークルの仲間とキャンプに行きました。', rom: 'サークルのなかまとキャンプにいきました。', ko: '동아리 친구들과 캠핑을 갔어요.' },
  '完全': { ex: '風邪はもう完全に治りました。', rom: 'かぜはもうかんぜんになおりました。', ko: '감기는 이제 완전히 나았어요.' },
  '命': { ex: '医者は多くの人の命を救います。', rom: 'いしゃはおおくのひとのいのちをすくいます。', ko: '의사는 많은 사람의 생명을 구해요.' },
  '人生': { ex: '人生は一度しかありません。', rom: 'じんせいはいちどしかありません。', ko: '인생은 한 번뿐이에요.' },
  '全員': { ex: '会議には全員参加してください。', rom: 'かいぎにはぜんいんさんかしてください。', ko: '회의에는 전원 참석해 주세요.' },
  '当然': { ex: '約束を守るのは、当然のことです。', rom: 'やくそくをまもるのは、とうぜんのことです。', ko: '약속을 지키는 건 당연한 일이에요.' },
  '独り': { ex: '父は独りで田舎に住んでいます。', rom: 'ちちはひとりでいなかにすんでいます。', ko: '아버지는 혼자 시골에 살고 계세요.' },
  '食う': { ex: '腹が減ったから、ラーメンでも食おう。', rom: 'はらがへったから、ラーメンでもくおう。', ko: '배고프니까 라면이라도 먹어요.' },
  '突然': { ex: '突然雨が降ってきて、びしょびしょになった。', rom: 'とつぜんあめがふってきて、びしょびしょになった。', ko: '갑자기 비가 내려서 흠뻑 젖었어요.' },
  '胸': { ex: '走ったあと、胸がどきどきしました。', rom: 'はしったあと、むねがどきどきしました。', ko: '달리고 나서 가슴이 두근거렸어요.' },
  '織る': { ex: '祖母は昔、着物の布を織っていました。', rom: 'そぼはむかし、きもののぬのをおっていました。', ko: '할머니는 예전에 기모노 천을 짜셨어요.' },
  'たしか': { ex: '会議はたしか三時からでしたよね。', rom: 'かいぎはたしかさんじからでしたよね。', ko: '회의는 아마 세 시부터였죠?' },
  '揚げる': { ex: '夕飯に天ぷらを揚げました。', rom: 'ゆうはんにてんぷらをあげました。', ko: '저녁으로 튀김을 튀겼어요.' },
  '挙げる': { ex: '例を一つ挙げてください。', rom: 'れいをひとつあげてください。', ko: '예를 하나 들어 주세요.' },
  'かなり': { ex: '今日はかなり寒いですね。', rom: 'きょうはかなりさむいですね。', ko: '오늘은 꽤 춥네요.' },
  '一体': { ex: '一体何があったんですか。', rom: 'いったいなにがあったんですか。', ko: '도대체 무슨 일이 있었던 거예요?' },
  '一帯': { ex: 'この辺り一帯は、昔は畑でした。', rom: 'このあたりいったいは、むかしははたけでした。', ko: '이 근처 일대는 옛날에 밭이었어요.' },
  '正直': { ex: '正直に言うと、あまり好きじゃないです。', rom: 'しょうじきにいうと、あまりすきじゃないです。', ko: '솔직히 말하면 별로 안 좋아해요.' },
  '澄む': { ex: '山の空気は澄んでいて気持ちがいいです。', rom: 'やまのくうきはすんでいてきもちがいいです。', ko: '산 공기는 맑아서 기분이 좋아요.' },
  '清む': { ex: '清んだ川で魚が泳いでいます。', rom: 'すんだかわでさかながおよいでいます。', ko: '맑은 강에서 물고기가 헤엄치고 있어요.' },
  'さて': { ex: 'さて、そろそろ会議を始めましょうか。', rom: 'さて、そろそろかいぎをはじめましょうか。', ko: '자, 슬슬 회의를 시작할까요?' },
  '結果': { ex: '試験の結果は来週わかります。', rom: 'しけんのけっかはらいしゅうわかります。', ko: '시험 결과는 다음 주에 나와요.' },
  '届く': { ex: '注文した本がやっと届きました。', rom: 'ちゅうもんしたほんがやっととどきました。', ko: '주문한 책이 드디어 도착했어요.' },
  '状態': { ex: 'この車はまだいい状態です。', rom: 'このくるまはまだいいじょうたいです。', ko: '이 차는 아직 상태가 좋아요.' },
  'それとも': { ex: 'コーヒーにしますか、それとも紅茶にしますか。', rom: 'コーヒーにしますか、それともこうちゃにしますか。', ko: '커피로 할래요, 아니면 홍차로 할래요?' },
  '方法': { ex: '一番いい方法を考えましょう。', rom: 'いちばんいいほうほうをかんがえましょう。', ko: '가장 좋은 방법을 생각해 봐요.' },
  '情報': { ex: 'インターネットで、旅行の情報を集めました。', rom: 'インターネットで、りょこうのじょうほうをあつめました。', ko: '인터넷으로 여행 정보를 모았어요.' },
  '最高': { ex: '今日は天気もよくて、最高の一日でした。', rom: 'きょうはてんきもよくて、さいこうのいちにちでした。', ko: '오늘은 날씨도 좋아서 최고의 하루였어요.' },
  '現れる': { ex: '約束の時間を過ぎて、やっと彼が現れました。', rom: 'やくそくのじかんをすぎて、やっとかれがあらわれました。', ko: '약속 시간이 지나서야 그가 나타났어요.' },
  '冗談': { ex: '今のは冗談だから、気にしないで。', rom: 'いまのはじょうだんだから、きにしないで。', ko: '방금 건 농담이니까 신경 쓰지 마요.' },
