  '求める': { ex: '店員に説明を求めました。', rom: 'てんいんにせつめいをもとめました。', ko: '점원에게 설명을 요구했어요.' },
  '理解': { ex: '先生の説明で、やっと理解できました。', rom: 'せんせいのせつめいで、やっとりかいできました。', ko: '선생님 설명을 듣고 겨우 이해했어요.' },
  '無事': { ex: '飛行機は無事に着きました。', rom: 'ひこうきはぶじにつきました。', ko: '비행기는 무사히 도착했어요.' },
  '当たる': { ex: '宝くじが当たりました!', rom: 'たからくじがあたりました!', ko: '복권에 당첨됐어요!' },
