  '感謝': { ex: '手伝ってくれた皆さんに感謝しています。', rom: 'てつだってくれたみなさんにかんしゃしています。', ko: '도와주신 여러분께 감사하고 있어요.' },
  '与える': { ex: 'ペットにえさを与えすぎないでください。', rom: 'ペットにえさをあたえすぎないでください。', ko: '반려동물에게 먹이를 너무 많이 주지 마세요.' },
  '王': { ex: '昔、この国には優しい王がいました。', rom: 'むかし、このくににはやさしいおうがいました。', ko: '옛날에 이 나라에는 다정한 왕이 있었어요.' },
