  '負う': { ex: '事故の責任は会社が負います。', rom: 'じこのせきにんはかいしゃがおいます。', ko: '사고 책임은 회사가 져요.' },
  '期待': { ex: '新しいドラマに、とても期待しています。', rom: 'あたらしいドラマに、とてもきたいしています。', ko: '새 드라마를 아주 기대하고 있어요.' },
  '気体': { ex: '水は熱すると気体になります。', rom: 'みずはねっするときたいになります。', ko: '물은 가열하면 기체가 돼요.' },
  '出会う': { ex: '夫とは旅行先で出会いました。', rom: 'おっととはりょこうさきでであいました。', ko: '남편과는 여행지에서 만났어요.' },
  '無し': { ex: '砂糖無しのコーヒーをください。', rom: 'さとうなしのコーヒーをください。', ko: '설탕 없는 커피 주세요.' },
  '当たり前': { ex: '遅刻したら謝るのは当たり前です。', rom: 'ちこくしたらあやまるのはあたりまえです。', ko: '지각하면 사과하는 건 당연해요.' },
  '目的': { ex: '旅行の目的は何ですか。', rom: 'りょこうのもくてきはなんですか。', ko: '여행 목적은 뭐예요?' },
  '瞬間': { ex: 'ドアを開けた瞬間、猫が飛び出してきました。', rom: 'ドアをあけたしゅんかん、ねこがとびだしてきました。', ko: '문을 연 순간 고양이가 튀어나왔어요.' },
  '不安': { ex: '一人で外国に行くのは、少し不安です。', rom: 'ひとりでがいこくにいくのは、すこしふあんです。', ko: '혼자 외국에 가는 건 조금 불안해요.' },
  '覚悟': { ex: '厳しい練習になることは覚悟しています。', rom: 'きびしいれんしゅうになることはかくごしています。', ko: '힘든 연습이 될 거라는 건 각오하고 있어요.' },
  '敵': { ex: '彼を敵にしたくありません。', rom: 'かれをてきにしたくありません。', ko: '그를 적으로 만들고 싶지 않아요.' },
  '拭く': { ex: '食事の後、テーブルを拭きました。', rom: 'しょくじのあと、テーブルをふきました。', ko: '식사 후에 테이블을 닦았어요.' },
  '福': { ex: '節分には「福は内」と言って豆をまきます。', rom: 'せつぶんには「ふくはうち」といってまめをまきます。', ko: '세쓰분에는 "복은 안으로"라고 말하며 콩을 뿌려요.' },
  '想像': { ex: '十年後の自分を想像してみてください。', rom: 'じゅうねんごのじぶんをそうぞうしてみてください。', ko: '10년 후의 자신을 상상해 보세요.' },
  '創造': { ex: '新しい文化を創造するのは大変です。', rom: 'あたらしいぶんかをそうぞうするのはたいへんです。', ko: '새로운 문화를 창조하는 건 힘들어요.' },
  'いつでも': { ex: '困ったら、いつでも連絡してください。', rom: 'こまったら、いつでもれんらくしてください。', ko: '곤란하면 언제든지 연락하세요.' },
