  '裏切る': { ex: '信じていた友達に裏切られました。', rom: 'しんじていたともだちにうらぎられました。', ko: '믿었던 친구에게 배신당했어요.' },
  '通じる': { ex: '英語が通じなくて困りました。', rom: 'えいごがつうじなくてこまりました。', ko: '영어가 안 통해서 곤란했어요.' },
