  '役': { ex: '劇で王子の役をやりました。', rom: 'げきでおうじのやくをやりました。', ko: '연극에서 왕자 역을 맡았어요.' },
  '約': { ex: '駅から会社まで約十分かかります。', rom: 'えきからかいしゃまでやくじっぷんかかります。', ko: '역에서 회사까지 약 10분 걸려요.' },
