  '依頼': { ex: '友達に翻訳を依頼しました。', rom: 'ともだちにほんやくをいらいしました。', ko: '친구에게 번역을 의뢰했어요.' },
  'ゲーム': { ex: '週末は家でゲームをして過ごしました。', rom: 'しゅうまつはいえでゲームをしてすごしました。', ko: '주말에는 집에서 게임을 하며 보냈어요.' },
