  '恋人': { ex: '恋人と一緒に花火を見に行きました。', rom: 'こいびとといっしょにはなびをみにいきました。', ko: '연인과 함께 불꽃놀이를 보러 갔어요.' },
  '真剣': { ex: '彼は真剣な顔で話を聞いていました。', rom: 'かれはしんけんなかおではなしをきいていました。', ko: '그는 진지한 얼굴로 이야기를 듣고 있었어요.' },
  '逆': { ex: '駅とは逆の方向に歩いてしまいました。', rom: 'えきとはぎゃくのほうこうにあるいてしまいました。', ko: '역과는 반대 방향으로 걸어가 버렸어요.' },
