  '輝く': { ex: '夜空に星が輝いています。', rom: 'よぞらにほしがかがやいています。', ko: '밤하늘에 별이 빛나고 있어요.' },
  '謎': { ex: '彼がなぜ会社を辞めたのかは謎です。', rom: 'かれがなぜかいしゃをやめたのかはなぞです。', ko: '그가 왜 회사를 그만뒀는지는 수수께끼예요.' },
  '何とか': { ex: '何とか締め切りに間に合いました。', rom: 'なんとかしめきりにまにあいました。', ko: '어떻게든 마감에 맞췄어요.' },
  '量': { ex: 'この店はご飯の量が多いです。', rom: 'このみせはごはんのりょうがおおいです。', ko: '이 가게는 밥 양이 많아요.' },
  '寮': { ex: '大学の寮に住んでいます。', rom: 'だいがくのりょうにすんでいます。', ko: '대학 기숙사에 살고 있어요.' },
  '普段': { ex: '普段は電車で会社に行きます。', rom: 'ふだんはでんしゃでかいしゃにいきます。', ko: '평소에는 전철로 회사에 가요.' },
  '菌': { ex: '手を洗って、菌を落としましょう。', rom: 'てをあらって、きんをおとしましょう。', ko: '손을 씻어서 균을 없애요.' },
  '違い': { ex: '二つの言葉の違いを教えてください。', rom: 'ふたつのことばのちがいをおしえてください。', ko: '두 단어의 차이를 알려 주세요.' },
  '酒': { ex: '父は毎晩少しだけ酒を飲みます。', rom: 'ちちはまいばんすこしだけさけをのみます。', ko: '아버지는 매일 밤 조금씩 술을 드세요.' },
