  '全身': { ex: '久しぶりに運動したら、全身が痛いです。', rom: 'ひさしぶりにうんどうしたら、ぜんしんがいたいです。', ko: '오랜만에 운동했더니 온몸이 아파요.' },
  '前進': { ex: '小さな一歩でも、前進は前進です。', rom: 'ちいさないっぽでも、ぜんしんはぜんしんです。', ko: '작은 한 걸음이라도 전진은 전진이에요.' },
