  '影': { ex: '夕方になると、影が長くなります。', rom: 'ゆうがたになると、かげがながくなります。', ko: '저녁이 되면 그림자가 길어져요.' },
  '陰': { ex: '暑いので、木の陰で休みましょう。', rom: 'あついので、きのかげでやすみましょう。', ko: '더우니까 나무 그늘에서 쉬어요.' },
