  '違いない': { ex: '電気がついているから、彼は家にいるに違いない。', rom: 'でんきがついているから、かれはいえにいるにちがいない。', ko: '불이 켜져 있으니까 그는 집에 있는 게 틀림없어요.' },
  'ショック': { ex: '大事なカップが割れて、ショックでした。', rom: 'だいじなカップがわれて、ショックでした。', ko: '아끼던 컵이 깨져서 충격이었어요.' },
  '証明': { ex: '身分を証明するものを持っていますか。', rom: 'みぶんをしょうめいするものをもっていますか。', ko: '신분을 증명할 수 있는 걸 가지고 있어요?' },
  '照明': { ex: '部屋の照明を少し暗くしました。', rom: 'へやのしょうめいをすこしくらくしました。', ko: '방 조명을 조금 어둡게 했어요.' },
