  '字体': { ex: 'この字体は読みやすくて好きです。', rom: 'このじたいはよみやすくてすきです。', ko: '이 글씨체는 읽기 쉬워서 좋아요.' },
  '辞退': { ex: '体調が悪いので、出場を辞退しました。', rom: 'たいちょうがわるいので、しゅつじょうをじたいしました。', ko: '몸이 안 좋아서 출전을 사퇴했어요.' },
  '予想': { ex: '試験は予想より簡単でした。', rom: 'しけんはよそうよりかんたんでした。', ko: '시험은 예상보다 쉬웠어요.' },
  'デート': { ex: '週末は彼女とデートする予定です。', rom: 'しゅうまつはかのじょとデートするよていです。', ko: '주말에는 여자 친구와 데이트할 예정이에요.' },
  '永遠': { ex: 'この日のことは永遠に忘れません。', rom: 'このひのことはえいえんにわすれません。', ko: '이날의 일은 영원히 잊지 않을 거예요.' },
  '興奮': { ex: '逆転ゴールに、観客はみんな興奮した。', rom: 'ぎゃくてんゴールに、かんきゃくはみんなこうふんした。', ko: '역전 골에 관중이 모두 흥분했어요.' },
  'ぶつかる': { ex: '自転車が電柱にぶつかった。', rom: 'じてんしゃがでんちゅうにぶつかった。', ko: '자전거가 전봇대에 부딪쳤어요.' },
  '見掛ける': { ex: '駅前で田中さんを見掛けました。', rom: 'えきまえでたなかさんをみかけました。', ko: '역 앞에서 다나카 씨를 봤어요.' },
  '抵抗': { ex: '新しいやり方に抵抗を感じる人も多い。', rom: 'あたらしいやりかたにていこうをかんじるひともおおい。', ko: '새로운 방식에 저항감을 느끼는 사람도 많아요.' },
  '女子': { ex: 'このクラスは女子のほうが多いです。', rom: 'このクラスはじょしのほうがおおいです。', ko: '이 반은 여학생이 더 많아요.' },
  '女史': { ex: '山田女史の講演は大好評だった。', rom: 'やまだじょしのこうえんはだいこうひょうだった。', ko: '야마다 여사의 강연은 큰 호평을 받았어요.' },
  '助詞': { ex: '日本語は助詞の使い方が難しい。', rom: 'にほんごはじょしのつかいかたがむずかしい。', ko: '일본어는 조사 쓰는 법이 어려워요.' },
  '先日': { ex: '先日はありがとうございました。', rom: 'せんじつはありがとうございました。', ko: '요전에는 정말 고마웠어요.' },
  '計': { ex: '参加者は計三十人でした。', rom: 'さんかしゃはけいさんじゅうにんでした。', ko: '참가자는 총 30명이었어요.' },
  '刑': { ex: '犯人は重い刑を受けた。', rom: 'はんにんはおもいけいをうけた。', ko: '범인은 무거운 형벌을 받았어요.' },
  '重ねる': { ex: '寒いので、服を何枚も重ねて着た。', rom: 'さむいので、ふくをなんまいもかさねてきた。', ko: '추워서 옷을 여러 겹 껴입었어요.' },
  '混乱': { ex: '事故で駅は大混乱になった。', rom: 'じこでえきはだいこんらんになった。', ko: '사고로 역은 큰 혼란에 빠졌어요.' },
  '提案': { ex: '会議で新しい企画を提案しました。', rom: 'かいぎであたらしいきかくをていあんしました。', ko: '회의에서 새로운 기획을 제안했어요.' },
  '攻める': { ex: '後半は相手チームが攻めてきた。', rom: 'こうはんはあいてチームがせめてきた。', ko: '후반에는 상대 팀이 공격해 왔어요.' },
  '責める': { ex: '失敗した人を責めてはいけません。', rom: 'しっぱいしたひとをせめてはいけません。', ko: '실패한 사람을 탓하면 안 돼요.' },
  '思わず': { ex: 'あまりにおかしくて、思わず笑ってしまった。', rom: 'あまりにおかしくて、おもわずわらってしまった。', ko: '너무 웃겨서 나도 모르게 웃어 버렸어요.' },
  '善': { ex: '子どもに善と悪の違いを教える。', rom: 'こどもにぜんとあくのちがいをおしえる。', ko: '아이에게 선과 악의 차이를 가르쳐요.' },
  '全': { ex: '全世界で人気のゲームです。', rom: 'ぜんせかいでにんきのゲームです。', ko: '전 세계에서 인기 있는 게임이에요.' },
  '膳': { ex: '旅館の夕食は、お膳で部屋に運ばれた。', rom: 'りょかんのゆうしょくは、おぜんでへやにはこばれた。', ko: '료칸의 저녁 식사는 상에 차려 방으로 나왔어요.' },
  '禅': { ex: '京都のお寺で禅を体験しました。', rom: 'きょうとのおてらでぜんをたいけんしました。', ko: '교토의 절에서 참선을 체험했어요.' },
  '穴': { ex: '靴下に穴が開いていました。', rom: 'くつしたにあながあいていました。', ko: '양말에 구멍이 나 있었어요.' },
  '苦しむ': { ex: '毎年、花粉症に苦しんでいる。', rom: 'まいとし、かふんしょうにくるしんでいる。', ko: '매년 꽃가루 알레르기로 고생하고 있어요.' },
  '武器': { ex: '英語が話せることは、彼の大きな武器だ。', rom: 'えいごがはなせることは、かれのおおきなぶきだ。', ko: '영어를 할 수 있다는 건 그의 큰 무기예요.' },
  '汗': { ex: '暑くて、シャツが汗でびっしょりです。', rom: 'あつくて、シャツがあせでびっしょりです。', ko: '더워서 셔츠가 땀으로 흠뻑 젖었어요.' },
  '恐怖': { ex: 'あの地震の恐怖は今でも忘れられない。', rom: 'あのじしんのきょうふはいまでもわすれられない。', ko: '그 지진의 공포는 지금도 잊을 수 없어요.' },
  'しまった': { ex: 'しまった、財布を家に忘れた。', rom: 'しまった、さいふをいえにわすれた。', ko: '아차, 지갑을 집에 두고 왔어요.' },
  '一方': { ex: '兄は明るい。一方、弟はおとなしい。', rom: 'あにはあかるい。いっぽう、おとうとはおとなしい。', ko: '형은 밝아요. 반면 남동생은 얌전해요.' },
  'なお': { ex: '薬を飲んだが、なお熱が下がらない。', rom: 'くすりをのんだが、なおねつがさがらない。', ko: '약을 먹었는데도 여전히 열이 안 내려요.' },
  '結ぶ': { ex: '靴のひもをしっかり結んでください。', rom: 'くつのひもをしっかりむすんでください。', ko: '신발 끈을 단단히 매 주세요.' },
  '恐れる': { ex: '失敗を恐れずに挑戦しよう。', rom: 'しっぱいをおそれずにちょうせんしよう。', ko: '실패를 두려워하지 말고 도전해요.' },
  '少年': { ex: 'その少年は毎日サッカーの練習をしている。', rom: 'そのしょうねんはまいにちサッカーのれんしゅうをしている。', ko: '그 소년은 매일 축구 연습을 해요.' },
  '秒': { ex: '百メートルを十二秒で走りました。', rom: 'ひゃくメートルをじゅうにびょうではしりました。', ko: '100미터를 12초에 달렸어요.' },
  '少々': { ex: '少々お待ちください。', rom: 'しょうしょうおまちください。', ko: '잠시만 기다려 주세요.' },
