  '派手': { ex: 'そのシャツ、ちょっと派手すぎない？', rom: 'そのシャツ、ちょっとはですぎない？', ko: '그 셔츠 좀 너무 화려하지 않아요?' },
  '燃える': { ex: '山火事で森が燃えている。', rom: 'やまかじでもりがもえている。', ko: '산불로 숲이 불타고 있어요.' },
  '優秀': { ex: '彼女はとても優秀な学生です。', rom: 'かのじょはとてもゆうしゅうながくせいです。', ko: '그녀는 아주 우수한 학생이에요.' },
  '外れる': { ex: 'シャツのボタンが外れていますよ。', rom: 'シャツのボタンがはずれていますよ。', ko: '셔츠 단추가 풀려 있어요.' },
  '多少': { ex: '多少高くても、質のいい物を買いたい。', rom: 'たしょうたかくても、しつのいいものをかいたい。', ko: '다소 비싸더라도 질 좋은 물건을 사고 싶어요.' },
  '写る': { ex: 'この写真、みんなよく写っていますね。', rom: 'このしゃしん、みんなよくうつっていますね。', ko: '이 사진 다들 잘 나왔네요.' },
  '映る': { ex: '湖に富士山が映っている。', rom: 'みずうみにふじさんがうつっている。', ko: '호수에 후지산이 비치고 있어요.' },
  'それと': { ex: 'コーヒーを一つ。それと、ケーキもお願いします。', rom: 'コーヒーをひとつ。それと、ケーキもおねがいします。', ko: '커피 하나요. 그리고 케이크도 부탁해요.' },
