  '閉じる': { ex: '目を閉じて、ゆっくり息をしてください。', rom: 'めをとじて、ゆっくりいきをしてください。', ko: '눈을 감고 천천히 숨을 쉬어 보세요.' },
  '綴じる': { ex: '書類をホッチキスで綴じておいてください。', rom: 'しょるいをホッチキスでとじておいてください。', ko: '서류를 스테이플러로 찍어 두세요.' },
