  'あるいは': { ex: '電話、あるいはメールで連絡してください。', rom: 'でんわ、あるいはメールでれんらくしてください。', ko: '전화 또는 이메일로 연락해 주세요.' },
  '禁止': { ex: 'ここでの撮影は禁止されています。', rom: 'ここでのさつえいはきんしされています。', ko: '여기서는 촬영이 금지돼 있어요.' },
  '近視': { ex: '近視なので、眼鏡がないと見えない。', rom: 'きんしなので、めがねがないとみえない。', ko: '근시라서 안경이 없으면 안 보여요.' },
