  '知識': { ex: '本を読んで、いろいろな知識を身につけたい。', rom: 'ほんをよんで、いろいろなちしきをみにつけたい。', ko: '책을 읽고 여러 가지 지식을 쌓고 싶어요.' },
  '疑問': { ex: '彼の説明には疑問が残る。', rom: 'かれのせつめいにはぎもんがのこる。', ko: '그의 설명에는 의문이 남아요.' },
  '年間': { ex: 'この町には年間百万人の観光客が来る。', rom: 'このまちにはねんかんひゃくまんにんのかんこうきゃくがくる。', ko: '이 마을에는 연간 백만 명의 관광객이 와요.' },
  '年鑑': { ex: '図書館で去年の年鑑を調べた。', rom: 'としょかんできょねんのねんかんをしらべた。', ko: '도서관에서 작년 연감을 찾아봤어요.' },
  '亡くす': { ex: '彼は子どものころに父親を亡くした。', rom: 'かれはこどものころにちちおやをなくした。', ko: '그는 어릴 때 아버지를 여의었어요.' },
  '作品': { ex: 'この監督の作品は、全部見ています。', rom: 'このかんとくのさくひんは、ぜんぶみています。', ko: '이 감독의 작품은 전부 봤어요.' },
  '美人': { ex: '彼のお姉さんはすごい美人だ。', rom: 'かれのおねえさんはすごいびじんだ。', ko: '그의 누나는 대단한 미인이에요.' },
  '休憩': { ex: '少し疲れたので、十分ほど休憩しましょう。', rom: 'すこしつかれたので、じゅっぷんほどきゅうけいしましょう。', ko: '조금 피곤하니까 10분쯤 쉬어요.' },
  '香り': { ex: '庭から花のいい香りがする。', rom: 'にわからはなのいいかおりがする。', ko: '정원에서 좋은 꽃향기가 나요.' },
  '追い付く': { ex: '走って前の人に追い付いた。', rom: 'はしってまえのひとにおいついた。', ko: '달려서 앞사람을 따라잡았어요.' },
  '沈む': { ex: '試験に落ちて、気分が沈んでいる。', rom: 'しけんにおちて、きぶんがしずんでいる。', ko: '시험에 떨어져서 기분이 가라앉아 있어요.' },
