  '溜まる': { ex: '仕事のストレスが溜まっている。', rom: 'しごとのストレスがたまっている。', ko: '일 스트레스가 쌓여 있어요.' },
  '埋める': { ex: '犬が庭に骨を埋めた。', rom: 'いぬがにわにほねをうめた。', ko: '개가 마당에 뼈를 묻었어요.' },
  '城': { ex: '丘の上に古い城がある。', rom: 'おかのうえにふるいしろがある。', ko: '언덕 위에 오래된 성이 있어요.' },
  '刺す': { ex: '蚊に刺されて、かゆい。', rom: 'かにさされて、かゆい。', ko: '모기에 물려서 가려워요.' },
  '指す': { ex: '先生は黒板の字を指した。', rom: 'せんせいはこくばんのじをさした。', ko: '선생님이 칠판의 글자를 가리켰어요.' },
  '挿す': { ex: '花瓶に花を挿した。', rom: 'かびんにはなをさした。', ko: '꽃병에 꽃을 꽂았어요.' },
