  '乾燥': { ex: '冬は空気が乾燥するので、肌が荒れやすい。', rom: 'ふゆはくうきがかんそうするので、はだがあれやすい。', ko: '겨울은 공기가 건조해서 피부가 거칠어지기 쉬워요.' },
  '感想': { ex: '映画の感想を聞かせてください。', rom: 'えいがのかんそうをきかせてください。', ko: '영화 본 소감을 들려주세요.' },
  '真っ赤': { ex: '恥ずかしくて顔が真っ赤になった。', rom: 'はずかしくてかおがまっかになった。', ko: '부끄러워서 얼굴이 새빨개졌어요.' },
