  '転ぶ': { ex: '雪の道で滑って転んでしまった。', rom: 'ゆきのみちですべってころんでしまった。', ko: '눈길에서 미끄러져 넘어지고 말았어요.' },
  '始まり': { ex: 'これが二人の恋の始まりだった。', rom: 'これがふたりのこいのはじまりだった。', ko: '이것이 두 사람 사랑의 시작이었어요.' },
  '個人': { ex: 'これはあくまで個人の意見です。', rom: 'これはあくまでこじんのいけんです。', ko: '이건 어디까지나 개인 의견이에요.' },
  '故人': { ex: '葬式で故人の思い出を語り合った。', rom: 'そうしきでこじんのおもいでをかたりあった。', ko: '장례식에서 고인과의 추억을 함께 이야기했어요.' },
  '党': { ex: '彼は新しい党を作った。', rom: 'かれはあたらしいとうをつくった。', ko: '그는 새로운 당을 만들었어요.' },
  '塔': { ex: '町のどこからでも、その塔が見える。', rom: 'まちのどこからでも、そのとうがみえる。', ko: '동네 어디에서나 그 탑이 보여요.' },
  '問う': { ex: '年齢や経験は問いません。', rom: 'ねんれいやけいけんはといません。', ko: '나이나 경험은 묻지 않아요.' },
  '棟': { ex: '新しい研究棟が来年完成する。', rom: 'あたらしいけんきゅうとうがらいねんかんせいする。', ko: '새 연구동이 내년에 완공돼요.' },
