  '案外': { ex: 'テストは案外簡単だった。', rom: 'テストはあんがいかんたんだった。', ko: '시험은 의외로 쉬웠어요.' },
  '幸い': { ex: '幸い、けが人はいなかった。', rom: 'さいわい、けがにんはいなかった。', ko: '다행히 다친 사람은 없었어요.' },
  '注文': { ex: 'ネットで本を注文した。', rom: 'ネットでほんをちゅうもんした。', ko: '인터넷으로 책을 주문했어요.' },
  '中央': { ex: '公園の中央に大きな噴水がある。', rom: 'こうえんのちゅうおうにおおきなふんすいがある。', ko: '공원 중앙에 큰 분수가 있어요.' },
  '男子': { ex: 'うちの学校は男子より女子が多い。', rom: 'うちのがっこうはだんしよりじょしがおおい。', ko: '우리 학교는 남학생보다 여학생이 많아요.' },
  '計算': { ex: '計算を間違えて、答えが合わなかった。', rom: 'けいさんをまちがえて、こたえがあわなかった。', ko: '계산을 틀려서 답이 안 맞았어요.' },
  '退く': { ex: '邪魔だから、そこをどいてくれる？', rom: 'じゃまだから、そこをどいてくれる？', ko: '방해되니까 거기서 좀 비켜 줄래요?' },
