  '笑い': { ex: '会場は笑いに包まれた。', rom: 'かいじょうはわらいにつつまれた。', ko: '행사장은 웃음바다가 됐어요.' },
  '増す': { ex: '雨で川の水が増している。', rom: 'あめでかわのみずがましている。', ko: '비 때문에 강물이 불어나고 있어요.' },
