  '脳': { ex: '寝ている間も、脳は働いている。', rom: 'ねているあいだも、のうははたらいている。', ko: '자는 동안에도 뇌는 일하고 있어요.' },
  '出会い': { ex: '旅先での出会いを大切にしている。', rom: 'たびさきでのであいをたいせつにしている。', ko: '여행지에서의 만남을 소중히 여겨요.' },
