  '手伝い': { ex: '引っ越しの手伝いに来てくれてありがとう。', rom: 'ひっこしのてつだいにきてくれてありがとう。', ko: '이사 도와주러 와 줘서 고마워요.' },
  'もしも': { ex: 'もしも地震が起きたら、机の下に隠れてください。', rom: 'もしもじしんがおきたら、つくえのしたにかくれてください。', ko: '만약 지진이 나면 책상 밑으로 숨으세요.' },
  '正式': { ex: '来週、正式に発表されるそうだ。', rom: 'らいしゅう、せいしきにはっぴょうされるそうだ。', ko: '다음 주에 정식으로 발표된대요.' },
  '羨ましい': { ex: '毎年海外旅行ができるなんて、羨ましい。', rom: 'まいとしかいがいりょこうができるなんて、うらやましい。', ko: '매년 해외여행을 갈 수 있다니 부러워요.' },
  'あちこち': { ex: '休みの日に、町のあちこちを歩いた。', rom: 'やすみのひに、まちのあちこちをあるいた。', ko: '쉬는 날에 동네 여기저기를 걸었어요.' },
  '携帯': { ex: '携帯を家に忘れてしまった。', rom: 'けいたいをいえにわすれてしまった。', ko: '휴대폰을 집에 두고 왔어요.' },
  '形態': { ex: '会社によって勤務形態はさまざまだ。', rom: 'かいしゃによってきんむけいたいはさまざまだ。', ko: '회사마다 근무 형태는 다양해요.' },
  '活躍': { ex: '彼は海外のチームで活躍している。', rom: 'かれはかいがいのチームでかつやくしている。', ko: '그는 해외 팀에서 활약하고 있어요.' },
  'のんびり': { ex: '休みの日は、家でのんびり過ごしたいです。', rom: 'やすみのひは、いえでのんびりすごしたいです。', ko: '쉬는 날에는 집에서 느긋하게 지내고 싶어요.' },
