  '悪魔': { ex: '昔話には、よく悪魔が出てくる。', rom: 'むかしばなしには、よくあくまがでてくる。', ko: '옛날이야기에는 악마가 자주 나와요.' },
  '結論': { ex: '長い会議の結果、ようやく結論が出た。', rom: 'ながいかいぎのけっか、ようやくけつろんがでた。', ko: '긴 회의 끝에 드디어 결론이 났어요.' },
  '飯': { ex: '腹が減ったな。飯でも食いに行こう。', rom: 'はらがへったな。めしでもくいにいこう。', ko: '배고프네요. 밥이라도 먹으러 가요.' },
  '例': { ex: '例を挙げて説明してください。', rom: 'れいをあげてせつめいしてください。', ko: '예를 들어서 설명해 주세요.' },
  '礼': { ex: '手伝ってくれた友達にお礼を言った。', rom: 'てつだってくれたともだちにおれいをいった。', ko: '도와준 친구에게 고맙다고 인사했어요.' },
  '注目': { ex: '新しいスマホが世界中から注目されている。', rom: 'あたらしいスマホがせかいじゅうからちゅうもくされている。', ko: '새 스마트폰이 전 세계에서 주목받고 있어요.' },
  '日常': { ex: '日常の小さな幸せを大切にしたい。', rom: 'にちじょうのちいさなしあわせをたいせつにしたい。', ko: '일상의 작은 행복을 소중히 하고 싶어요.' },
  '処理': { ex: '今日中にこの仕事を処理しなければならない。', rom: 'きょうじゅうにこのしごとをしょりしなければならない。', ko: '오늘 안에 이 일을 처리해야 해요.' },
  '次々': { ex: '新しい店が次々にオープンしている。', rom: 'あたらしいみせがつぎつぎにオープンしている。', ko: '새 가게들이 잇달아 문을 열고 있어요.' },
  'いわゆる': { ex: '彼はいわゆる天才だ。', rom: 'かれはいわゆるてんさいだ。', ko: '그는 이른바 천재예요.' },
  '保証': { ex: 'この時計には一年間の保証がついている。', rom: 'このとけいにはいちねんかんのほしょうがついている。', ko: '이 시계는 1년 동안 보증이 돼요.' },
  '保障': { ex: '国民の生活を保障するのは国の仕事だ。', rom: 'こくみんのせいかつをほしょうするのはくにのしごとだ。', ko: '국민의 생활을 보장하는 건 나라가 할 일이에요.' },
  '補償': { ex: '事故の被害者に補償金が支払われた。', rom: 'じこのひがいしゃにほしょうきんがしはらわれた。', ko: '사고 피해자에게 보상금이 지급됐어요.' },
  'ぴったり': { ex: 'この靴、サイズがぴったりです。', rom: 'このくつ、サイズがぴったりです。', ko: '이 신발 사이즈가 딱 맞아요.' },
  '魅力': { ex: 'この町の魅力は、何といっても海の景色だ。', rom: 'このまちのみりょくは、なんといってもうみのけしきだ。', ko: '이 마을의 매력은 뭐니 뭐니 해도 바다 풍경이에요.' },
  '夫婦': { ex: 'あの夫婦は、いつも仲がいいですね。', rom: 'あのふうふは、いつもなかがいいですね。', ko: '저 부부는 항상 사이가 좋네요.' },
  'メッセージ': { ex: '誕生日に、友達からメッセージが届きました。', rom: 'たんじょうびに、ともだちからメッセージがとどきました。', ko: '생일에 친구에게서 메시지가 왔어요.' },
  '質': { ex: '値段より質を重視している。', rom: 'ねだんよりしつをじゅうししている。', ko: '가격보다 품질을 중시해요.' },
