  '課程': { ex: '大学院の博士課程に進んだ。', rom: 'だいがくいんのはかせかていにすすんだ。', ko: '대학원 박사 과정에 진학했어요.' },
  '治療': { ex: '歯の治療は、あと二回で終わるそうです。', rom: 'はのちりょうは、あとにかいでおわるそうです。', ko: '치아 치료는 앞으로 두 번이면 끝난대요.' },
  '腐る': { ex: '冷蔵庫の牛乳が腐っていた。', rom: 'れいぞうこのぎゅうにゅうがくさっていた。', ko: '냉장고 우유가 상해 있었어요.' },
