  '数字': { ex: 'パスワードには数字を入れてください。', rom: 'パスワードにはすうじをいれてください。', ko: '비밀번호에는 숫자를 넣어 주세요.' },
  '達する': { ex: '参加者は千人に達する見込みだ。', rom: 'さんかしゃはせんにんにたっするみこみだ。', ko: '참가자는 천 명에 달할 전망이에요.' },
