  '特長': { ex: 'この掃除機の特長は音が静かなことだ。', rom: 'このそうじきのとくちょうはおとがしずかなことだ。', ko: '이 청소기의 장점은 소리가 조용하다는 거예요.' },
  'グループ': { ex: 'グループに分かれて話し合ってください。', rom: 'グループにわかれてはなしあってください。', ko: '그룹으로 나뉘어서 의논해 주세요.' },
  '上る': { ex: '階段を上って三階へ行く。', rom: 'かいだんをのぼってさんかいへいく。', ko: '계단을 올라 3층으로 가요.' },
