  '集団': { ex: '小学生が集団で登校している。', rom: 'しょうがくせいがしゅうだんでとうこうしている。', ko: '초등학생들이 무리 지어 등교하고 있어요.' },
  '覗く': { ex: '窓から部屋の中を覗いた。', rom: 'まどからへやのなかをのぞいた。', ko: '창문으로 방 안을 들여다봤어요.' },
  '除く': { ex: '日曜日を除いて、毎日営業しています。', rom: 'にちようびをのぞいて、まいにちえいぎょうしています。', ko: '일요일을 제외하고 매일 영업해요.' },
