  '親しい': { ex: '彼女とは学生時代から親しい。', rom: 'かのじょとはがくせいじだいからしたしい。', ko: '그녀와는 학생 때부터 친해요.' },
  '持ち上げる': { ex: '重い箱を一人で持ち上げた。', rom: 'おもいはこをひとりでもちあげた。', ko: '무거운 상자를 혼자서 들어 올렸어요.' },
